import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { pathToFileURL, fileURLToPath } from "node:url";
import { sourceKey } from "./native-sources.mjs";
const require = createRequire(import.meta.url);
import { mockSourceMap } from "./mock-source-map.mjs";
const { parse } = createRequire(require.resolve("vitest"))("acorn");
import { appendFile } from "node:fs/promises";
import stock from "../../.coverage-experiment/original-converter.mjs";
import candidate from "../../.coverage-experiment/converter.mjs";
// Vitest 5 native mocks generate a proxy under the application's URL, but its
// coverage provider supplies the original disk source for that proxy. Manual
// proxies use verified generated bytes; unqualified kinds remain rejected.
export default async function convert(options) {
	if(process.env.EXPERIMENT_CAPTURE_FACTORY && /\/apps\/factory\/src\/adapters\/(github\/joins|t3\/planner)\.js$/.test(options.coverage.url) && options.coverage.functions.length)
		await appendFile(process.env.EXPERIMENT_CAPTURE_FACTORY,JSON.stringify({...options,ast:await options.ast})+'\n');
	if (
		process.env.EXPERIMENT_CAPTURE_RECOVERY &&
		options.coverage.url.endsWith("/picture-attachments/recovery.js") &&
		options.coverage.functions.length
	)
		await appendFile(
			process.env.EXPERIMENT_CAPTURE_RECOVERY,
			JSON.stringify({ ...options, ast: await options.ast }) + "\n",
		);

	if (
		["manual", "automock", "autospy"].includes(
			new URL(options.coverage.url).searchParams.get("mock"),
		) &&
		process.env.EXPERIMENT_NATIVE_SOURCES
	) {
		const key = sourceKey(options.coverage.url);
		const record = JSON.parse(
			await readFile(
				`${process.env.EXPERIMENT_NATIVE_SOURCES}/${key}.json`,
				"utf8",
			),
		);
		if (record.url !== options.coverage.url)
			throw new Error("Generated source identity mismatch");
		if (new URL(options.coverage.url).searchParams.get("mock") !== "manual") {
			const inline = [
				...record.code.matchAll(
					/sourceMappingURL=data:application\/json;base64,([^\s]+)/g,
				),
			].at(-1)?.[1];
			if (!inline)
				throw new Error("NATIVE_MOCK_SOURCE_MISMATCH: generated map missing");
			const outer = JSON.parse(Buffer.from(inline, "base64").toString());
			if (outer.sources?.[0] !== fileURLToPath(options.coverage.url))
				throw new Error(
					"NATIVE_MOCK_SOURCE_MISMATCH: generated map origin differs from loaded application",
				);
			const code = await readFile(fileURLToPath(options.coverage.url), "utf8");
			const mapName = [...code.matchAll(/sourceMappingURL=([^\s]+)/g)].at(
				-1,
			)?.[1];
			if (!mapName)
				throw new Error("NATIVE_MOCK_SOURCE_MISMATCH: application map missing");
			const inner = JSON.parse(
				await readFile(new URL(mapName, options.coverage.url), "utf8"),
			);
			const map = mockSourceMap(
				outer,
				inner,
				code,
				record.code,
				`${process.env.EXPERIMENT_NATIVE_SOURCES}/${key}.js`,
			);
			return candidate({
				...options,
				code: record.code,
				ast: parse(record.code, {
					ecmaVersion: "latest",
					sourceType: "module",
				}),
				sourceMap: map,
			});
		}
		// Synthetic proxy bytes have no original application source correspondence.
		// Keep their measurements under their own explicit identity. The provider's
		// complete inventory then adds unexecuted original source with zero counts.
		return candidate({
			...options,
			code: record.code,
			ast: parse(record.code, { ecmaVersion: "latest", sourceType: "module" }),
			sourceMap: undefined,
			coverage: {
				...options.coverage,
				url: pathToFileURL(`${process.env.EXPERIMENT_NATIVE_SOURCES}/${key}.js`)
					.href,
			},
		});
	}

	if (
		["manual", "automock", "autospy"].includes(
			new URL(options.coverage.url).searchParams.get("mock"),
		)
	) {
		throw new Error(
			"NATIVE_MOCK_SOURCE_MISMATCH: application mock proxy cannot be attributed to original disk source; retain the Vite runner for this suite",
		);
	}
	if (process.env.EXPERIMENT_COMPARE_STOCK === "1") {
		const ast = await options.ast;
		const baselineAst = structuredClone(ast);
		const result = await candidate({ ...options, ast });
		const baseline = await stock({ ...options, ast: baselineAst });
		const counters = (map) =>
			Object.fromEntries(
				Object.entries(map).map(([file, data]) => [
					file,
					{ s: data.s, f: data.f, b: data.b },
				]),
			);
		await appendFile(
			"/tmp/wallpaperdb-742/adoption/native-stock-replay.jsonl",
			JSON.stringify({
				url: options.coverage.url,
				equal:
					JSON.stringify(counters(result)) ===
					JSON.stringify(counters(baseline)),
			}) + "\n",
		);
		return result;
	}
	return candidate(options);
}
